from functools import reduce

def is_balanced_parentheses(s):
    def step(depth, ch):
        if depth is None:
            return None
        if ch == '(':
            return depth + 1
        if ch == ')':
            return None if depth == 0 else depth - 1
        return depth
    final = reduce(step, s, 0)
    return final == 0

